import { describe, expect, it } from 'vitest'
import {
  notebookCellRepairMediaLabel,
  notebookCellRepairPrompt,
} from '../../src/videobook/notebook-cell-repair'

describe('notebookCellRepairPrompt', () => {
  it('names the output, its producer, the error and the generator', () => {
    expect(notebookCellRepairPrompt({
      address: '@c4',
      error: ' Fal failed: Fal API error: 422 ',
      mediaLabel: 'video',
      producerAddress: '@b2',
      provider: 'fal',
      model: 'bytedance/seedance-2-5',
    })).toBe(
      'Repair @c4: the video generated by @b2 failed with "Fal failed: Fal API error: 422". '
      + 'Generator: fal · bytedance/seedance-2-5. '
      + 'Inspect the recorded provider request and the settings on @b2, fix what the provider rejected, and re-run @b2 into @c4 as a preview.',
    )
  })

  it('addresses a generation cell that failed on its own', () => {
    expect(notebookCellRepairPrompt({
      address: '@b1',
      error: 'Job lease expired',
      mediaLabel: 'video',
      producerAddress: null,
      provider: null,
      model: 'wan/v3.0/r2v',
    })).toBe(
      'Repair @b1: the video failed with "Job lease expired". '
      + 'Generator: wan/v3.0/r2v. '
      + 'Inspect the recorded provider request and this cell\'s settings, fix what the provider rejected, and re-run @b1 as a preview.',
    )
  })

  it('falls back to a generic error and omits an unknown generator', () => {
    expect(notebookCellRepairPrompt({
      address: '@a3',
      error: '   ',
      mediaLabel: 'image',
      producerAddress: null,
      provider: null,
      model: null,
    })).toBe(
      'Repair @a3: the image failed with "the provider rejected the request". '
      + 'Inspect the recorded provider request and this cell\'s settings, fix what the provider rejected, and re-run @a3 as a preview.',
    )
  })
})

describe('notebookCellRepairMediaLabel', () => {
  it('reads the media kind off generation and output cell types', () => {
    expect(notebookCellRepairMediaLabel('video')).toBe('video')
    expect(notebookCellRepairMediaLabel('generate_video')).toBe('video')
    expect(notebookCellRepairMediaLabel('image')).toBe('image')
    expect(notebookCellRepairMediaLabel('generate_image')).toBe('image')
    expect(notebookCellRepairMediaLabel('generate_audio')).toBe('audio')
    expect(notebookCellRepairMediaLabel('analyze')).toBe('generation')
  })
})
